1	// In-process, time bounded lease registry.
2	// Time only moves when the injected clock moves; nothing expires on its own.
3	
4	export class LeaseTakenError extends Error {
5	  constructor(resource, holder) {
6	    super(`lease for resource ${String(resource)} is already held`);
7	    this.name = 'LeaseTakenError';
8	    this.code = LeaseTakenError.code;
9	    this.resource = resource;
10	    this.holder = holder ?? null;
11	  }
12	}
13	LeaseTakenError.code = 'LEASE_TAKEN';
14	
15	export function createRegistry({ ttlMs, clock = Date.now } = {}) {
16	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
17	    throw new TypeError('ttlMs must be a positive finite number');
18	  }
19	  if (typeof clock !== 'function') {
20	    throw new TypeError('clock must be a function');
21	  }
22	
23	  const defaultTtlMs = ttlMs;
24	  // token -> { resource, holder, expiresAt, ttlMs, released }
25	  const leases = new Map();
26	  // resource -> token of the lease currently occupying it
27	  const occupied = new Map();
28	
29	  const counters = {
30	    granted: 0,
31	    renewed: 0,
32	    released: 0,
33	    reclaimed: 0,
34	  };
35	
36	  function isLive(lease, now) {
37	    return lease !== undefined && !lease.released && lease.expiresAt > now;
38	  }
39	
40	  function acquire(resource, holder, ttlMs = defaultTtlMs) {
41	    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
42	      throw new TypeError('ttlMs must be a positive finite number');
43	    }
44	    const now = clock();
45	    const currentToken = occupied.get(resource);
46	    if (currentToken !== undefined) {
47	      const current = leases.get(currentToken);
48	      if (isLive(current, now)) {
49	        throw new LeaseTakenError(resource, current.holder);
50	      }
51	      // Expired but not yet swept: the resource is free. Drop the stale
52	      // record (sweep never reclaims a resource that was already retaken).
53	      occupied.delete(resource);
54	      leases.delete(currentToken);
55	    }
56	
57	    const token = makeToken();
58	    const lease = {
59	      resource,
60	      holder,
61	      expiresAt: now + ttlMs,
62	      ttlMs,
63	      released: false,
64	    };
65	    leases.set(token, lease);
66	    occupied.set(resource, token);
67	    counters.granted += 1;
68	
69	    return {
70	      resource,
71	      holder,
72	      token,
73	      expiresAt: lease.expiresAt,
74	    };
75	  }
76	
77	  function renew(token) {
78	    const lease = leases.get(token);
79	    if (lease === undefined || lease.released) {
80	      return false;
81	    }
82	    const now = clock();
83	    if (lease.expiresAt <= now) {
84	      return false;
85	    }
86	    lease.expiresAt = now + lease.ttlMs;
87	    counters.renewed += 1;
88	    return true;
89	  }
90	
91	  function release(token) {
92	    const lease = leases.get(token);
93	    if (lease === undefined || lease.released) {
94	      return false;
95	    }
96	    const now = clock();
97	    if (lease.expiresAt <= now) {
98	      return false;
99	    }
100	    lease.released = true;
101	    if (occupied.get(lease.resource) === token) {
102	      occupied.delete(lease.resource);
103	    }
104	    counters.released += 1;
105	    return true;
106	  }
107	
108	  function sweep(now = clock()) {
109	    const expired = [];
110	    for (const [token, lease] of leases) {
111	      if (lease.released) {
112	        // Credential is already dead; nothing to report or count.
113	        leases.delete(token);
114	        continue;
115	      }
116	      if (lease.expiresAt <= now) {
117	        expired.push([token, lease]);
118	      }
119	    }
120	    // Reclaim in expiry order (acquisition order breaks ties).
121	    expired.sort((a, b) => a[1].expiresAt - b[1].expiresAt);
122	
123	    const freed = [];
124	    for (const [token, lease] of expired) {
125	      leases.delete(token);
126	      if (occupied.get(lease.resource) === token) {
127	        occupied.delete(lease.resource);
128	        counters.reclaimed += 1;
129	        freed.push(lease.resource);
130	      }
131	      // Otherwise the resource was already retaken by a new holder; this
132	      // stale credential is discarded silently.
133	    }
134	    return freed;
135	  }
136	
137	  function holder(resource) {
138	    const token = occupied.get(resource);
139	    if (token === undefined) {
140	      return null;
141	    }
142	    const lease = leases.get(token);
143	    if (!isLive(lease, clock())) {
144	      return null;
145	    }
146	    return lease.holder;
147	  }
148	
149	  function stats() {
150	    let live = 0;
151	    const now = clock();
152	    for (const token of occupied.values()) {
153	      const lease = leases.get(token);
154	      if (isLive(lease, now)) {
155	        live += 1;
156	      }
157	    }
158	    return {
159	      granted: counters.granted,
160	      renewed: counters.renewed,
161	      released: counters.released,
162	      reclaimed: counters.reclaimed,
163	      live,
164	    };
165	  }
166	
167	  return { acquire, renew, release, sweep, holder, stats };
168	}
169	
170	let tokenSequence = 0;
171	function makeToken() {
172	  tokenSequence += 1;
173	  return `lease-${process.pid}-${tokenSequence}-${Date.now().toString(36)}`;
174	}
